"372\" text-anchor=\"middle\">COUPLING</text><rect x=\"156\" y=\"387\" width=\"80\" height=\"19\" rx=\"5\" fill=\"rgba(201,162,39,0.22)\" stroke=\"#C9A227\" stroke-width=\"1.8\"/><text class=\"tg\" x=\"164\" y=\"400\" >DC</text><text class=\"t12\" x=\"164\" y=\"420\" >AC</text><text class=\"t12\" x=\"164\" y=\"440\" >GND</text><line x1=\"140\" y1=\"395\" x2=\"148\" y2=\"395\" stroke=\"#C9A227\" stroke-width=\"3\" stroke-linecap=\"round\"/><circle cx=\"330\" cy=\"412\" r=\"17\" fill=\"#ffffff\" stroke=\"#010080\" stroke-width=\"2.2\"/><circle cx=\"330\" cy=\"412\" r=\"6\" fill=\"#010080\"/><text class=\"tb\" x=\"330\" y=\"446\" text-anchor=\"middle\">CH2</text><rect x=\"384\" y=\"380\" width=\"92\" height=\"74\" rx=\"8\" fill=\"#ffffff\" stroke=\"#010080\" stroke-width=\"2\"/><text class=\"tb\" x=\"430\" y=\"372\" text-anchor=\"middle\">COUPLING</text><text class=\"t12\" x=\"398\" y=\"400\" >DC</text><text class=\"t12\" x=\"398\" y=\"420\" >AC</text><rect x=\"390\" y=\"427\" width=\"80\" height=\"19\" rx=\"5\" fill=\"rgba(201,162,39,0.22)\" stroke=\"#C9A227\" stroke-width=\"1.8\"/><text class=\"tg\" x=\"398\" y=\"440\" >GND</text><line x1=\"374\" y1=\"435\" x2=\"382\" y2=\"435\" stroke=\"#C9A227\" stroke-width=\"3\" stroke-linecap=\"round\"/><text class=\"t12\" x=\"40\" y=\"470\" >Dual trace: one cycle spans 8 divisions and B crosses zero 1 division after A &#8594; phase = 45&#176;.</text></svg>",
